@register.filter(is_safe=True)
def intcomma(value, use_l10n=True):
    """
    Convert an integer or float to a string containing commas every three digits.
    For example, 3000 becomes '3,000' and 45000 becomes '45,000'.
    """
    import re
    from decimal import Decimal

    try:
        value = Decimal(value)
    except (TypeError, ValueError, InvalidOperation):
        return value

    int_part, _, frac_part = str(value).partition('.')

    def add_commas_to_integer_part(s):
        if s.startswith('-'):
            sign = '-'
            s = s[1:]
        else:
            sign = ''
        return sign + re.sub(r"(?<=\d)(?=(\d{3})+$)", ",", s[::-1])[::-1]

    int_part_with_commas = add_commas_to_integer_part(int_part)
    return f"{int_part_with_commas}.{frac_part}" if frac_part else int_part_with_commas
